Here's an implementation of the Fibonacci sequence using a recursive function in C++:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <limits> // for numeric_limits

// Function to generate Fibonacci sequence recursively
unsigned long long fibonacci(unsigned int n, unsigned long long a, unsigned long long b) {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    std::string input;
    std::getline(std::cin, input); // read entire line including whitespace

    std::stringstream ss(input); // convert string to stream
    unsigned int first, second, num;

    // Parse input values
    if (!(ss >> first >> second >> num)) { // check if input is valid
        std::cerr << "Invalid input!\n";
        return 1;
    }

    // Check for negative input values
    if (first < 0 || second < 0 || num < 0) {
        std::cerr << "Input values cannot be negative!\n";
        return 1;
    }

    // Generate Fibonacci sequence
    unsigned long long result = fibonacci(num, first, second);

    // Output generated sequence
    std::cout << first << ", " << second << " ";
    while (result != 0) {
        std::cout << result << ", ";
        result = fibonacci(num - 1, second, result);
    }

    return 0;
}
```

