Here's a C++ implementation of Bubble Sort for your given JSON input:

```cpp
#include <iostream>
#include <cjson/cJSON.h> // Required for parsing JSON
#include <vector>

const int MAX_SIZE = 100; // Maximum size of array

// Bubble Sort function
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped = false;
    for (int i = 0; i < n-1; ++i) {
        swapped = false;
        for (int j = 0; j < n-i-1; ++j) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
        if (!swapped) break; // If no swaps were made, array is sorted
    }
}

